insert into ticket_comments values (1, 1, 'Agent', 'Daniel Okafor', 'Administrators can require two-factor authentication under Settings > Security > Sign-in policy. Rejected codes usually mean the phone clock is wrong; enable automatic time on the phone. See article KB-103.', timestamp '2026-05-03 07:50:00');
insert into ticket_comments values (2, 1, 'Customer', 'Leo Haddad', 'Thanks, the problem is solved.', timestamp '2026-05-03 10:49:00');
insert into ticket_comments values (3, 3, 'Agent', 'Priya Raman', 'Version 3.9.0 crashes when the offline database is larger than 2 GB. Version 3.9.1 fixes it; until it reaches your store, sign out and in again to rebuild the offline data. See article KB-401.', timestamp '2026-03-30 12:47:00');
insert into ticket_comments values (4, 4, 'Agent', 'Priya Raman', 'Go to Connect > Connectors, choose Microsoft 365 or Google Workspace, and sign in. Meetings sync both ways every five minutes. See article KB-603.', timestamp '2026-01-23 09:55:00');
insert into ticket_comments values (5, 5, 'Agent', 'Daniel Okafor', 'A report schedule pauses after three failed deliveries, for example when a recipient address bounces. Remove the bouncing address and resume the schedule under Reports > Schedules. See article KB-501.', timestamp '2026-01-15 16:26:00');
insert into ticket_comments values (6, 5, 'Customer', 'Ravi Wong', 'That worked, thank you!', timestamp '2026-01-17 12:49:00');
insert into ticket_comments values (7, 6, 'Agent', 'Yusuf Demir', 'Invoice templates support up to five custom fields today under Billing > Templates. I have also passed your request for more fields to the product team. See article KB-205.', timestamp '2026-06-30 12:34:00');
insert into ticket_comments values (8, 6, 'Customer', 'Zara Sato', 'Can you confirm when the fix is released?', timestamp '2026-07-01 04:04:00');
insert into ticket_comments values (9, 7, 'Agent', 'Yusuf Demir', 'The importer matches on e-mail address only. Use Contacts > Find duplicates to merge them, and choose "Update existing records" the next time you import. See article KB-302.', timestamp '2026-09-13 23:00:00');
insert into ticket_comments values (10, 8, 'Agent', 'Arjun Mehta', 'Use Forecasts > New forecast and choose "Weighted by stage probability". Each stage has a probability you can change under Pipeline settings. See article KB-303.', timestamp '2026-09-17 18:47:00');
insert into ticket_comments values (11, 10, 'Agent', 'Arjun Mehta', 'The importer matches on e-mail address only. Use Contacts > Find duplicates to merge them, and choose "Update existing records" the next time you import. See article KB-302.', timestamp '2026-09-11 13:55:00');
insert into ticket_comments values (12, 11, 'Agent', 'Arjun Mehta', 'Webhooks are disabled after 24 hours of failed deliveries. Your endpoint returned HTTP 500. Fix the endpoint and re-enable the webhook under Connect > Webhooks; missed events can be replayed from there. See article KB-601.', timestamp '2026-04-25 22:52:00');
insert into ticket_comments values (13, 12, 'Agent', 'Yusuf Demir', 'Thank you for the suggestion. Dark mode is on the roadmap for the second half of the year; I have added your vote.', timestamp '2026-09-21 05:10:00');
insert into ticket_comments values (14, 13, 'Agent', 'Hannah Becker', 'I have signed out all sessions and required a new password. Please turn on two-factor authentication; the sign-in history is under Settings > Security > Activity. See article KB-105.', timestamp '2026-03-31 15:03:00');
insert into ticket_comments values (15, 14, 'Agent', 'Priya Raman', 'Analytics shows revenue by payment date and excludes unpaid invoices, while Billing lists invoices by issue date. Switch the dashboard filter to "Issue date" to compare them. See article KB-503.', timestamp '2026-05-30 13:19:00');
insert into ticket_comments values (16, 15, 'Agent', 'Emma Lindqvist', 'The second charge was a retry after a timeout at the payment gateway. I have refunded it; banks show the refund within 5 to 10 business days. See article KB-201.', timestamp '2026-05-17 02:19:00');
insert into ticket_comments values (17, 17, 'Agent', 'Arjun Mehta', 'Offline edits are kept for 7 days. If someone edits the same record on the web, the newer change wins. Check Settings > Sync > Conflicts for edits that were not applied. See article KB-402.', timestamp '2026-08-04 00:44:00');
insert into ticket_comments values (18, 17, 'Customer', 'Mei Petrova', 'That worked, thank you!', timestamp '2026-08-05 16:11:00');
insert into ticket_comments values (19, 18, 'Agent', 'Liam Chen', 'Invoice templates support up to five custom fields today under Billing > Templates. I have also passed your request for more fields to the product team. See article KB-205.', timestamp '2026-04-01 17:59:00');
insert into ticket_comments values (20, 18, 'Customer', 'Omar Karimi', 'It still does not work for two of our users.', timestamp '2026-04-02 14:49:00');
insert into ticket_comments values (21, 19, 'Agent', 'Priya Raman', 'A report schedule pauses after three failed deliveries, for example when a recipient address bounces. Remove the bouncing address and resume the schedule under Reports > Schedules. See article KB-501.', timestamp '2026-04-21 21:12:00');
insert into ticket_comments values (22, 19, 'Customer', 'Olivia Wong', 'Can you confirm when the fix is released?', timestamp '2026-04-22 20:51:00');
insert into ticket_comments values (23, 20, 'Agent', 'Liam Chen', 'Use Forecasts > New forecast and choose "Weighted by stage probability". Each stage has a probability you can change under Pipeline settings. See article KB-303.', timestamp '2026-04-25 02:19:00');
insert into ticket_comments values (24, 21, 'Agent', 'Emma Lindqvist', 'The second charge was a retry after a timeout at the payment gateway. I have refunded it; banks show the refund within 5 to 10 business days. See article KB-201.', timestamp '2026-05-19 04:11:00');
insert into ticket_comments values (25, 22, 'Agent', 'Daniel Okafor', 'This is a known issue in 8.4.0 with pipelines that have more than 100 stages of custom fields. It is fixed in 8.4.1; as a workaround, hide unused custom fields on the board. See article KB-301.', timestamp '2026-07-11 10:20:00');
insert into ticket_comments values (26, 22, 'Customer', 'Aisha Taylor', 'Thanks, the problem is solved.', timestamp '2026-07-13 01:36:00');
insert into ticket_comments values (27, 23, 'Agent', 'Sofia Marquez', 'Thank you for the suggestion. Dark mode is on the roadmap for the second half of the year; I have added your vote.', timestamp '2026-09-04 06:26:00');
insert into ticket_comments values (28, 24, 'Agent', 'Hannah Becker', 'The API allows 120 requests per minute on Basic, 600 on Professional, and 3,000 on Enterprise. Use the bulk endpoints and honor the Retry-After header. See article KB-602.', timestamp '2026-03-13 09:41:00');
insert into ticket_comments values (29, 24, 'Customer', 'Omar Dubois', 'Perfect, much appreciated.', timestamp '2026-03-14 00:27:00');
insert into ticket_comments values (30, 26, 'Agent', 'Emma Lindqvist', 'All invoices are under Billing > Invoices; filter by date and use Download all to get one ZIP file of PDFs. See article KB-202.', timestamp '2026-02-15 16:10:00');
insert into ticket_comments values (31, 26, 'Customer', 'Noah Iyer', 'Perfect, much appreciated.', timestamp '2026-02-17 11:40:00');
insert into ticket_comments values (32, 27, 'Agent', 'Liam Chen', 'Sync stops on files with names longer than 255 characters or with characters such as : or ?. Open the app log, rename the listed files, and choose "Retry all". See article KB-701.', timestamp '2026-01-28 19:17:00');
