insert into ticket_comments values (284, 233, 'Agent', 'Yusuf Demir', 'A report schedule pauses after three failed deliveries, for example when a recipient address bounces. Remove the bouncing address and resume the schedule under Reports > Schedules. See article KB-501.', timestamp '2026-02-18 00:31:00');
insert into ticket_comments values (285, 234, 'Agent', 'Yusuf Demir', 'Invoice templates support up to five custom fields today under Billing > Templates. I have also passed your request for more fields to the product team. See article KB-205.', timestamp '2026-03-25 07:23:00');
insert into ticket_comments values (286, 234, 'Customer', 'Lucas Novak', 'Can you confirm when the fix is released?', timestamp '2026-03-25 15:18:00');
insert into ticket_comments values (287, 235, 'Agent', 'Daniel Okafor', 'Accounts lock for 15 minutes after five failed sign-ins. I have unlocked the account and sent a new reset link; please use the newest link only, older links expire after one hour. See article KB-101.', timestamp '2026-02-28 19:33:00');
insert into ticket_comments values (288, 236, 'Agent', 'Yusuf Demir', 'A report schedule pauses after three failed deliveries, for example when a recipient address bounces. Remove the bouncing address and resume the schedule under Reports > Schedules. See article KB-501.', timestamp '2026-01-21 00:55:00');
insert into ticket_comments values (289, 237, 'Agent', 'Priya Raman', 'Go to Connect > Connectors, choose Microsoft 365 or Google Workspace, and sign in. Meetings sync both ways every five minutes. See article KB-603.', timestamp '2026-04-14 18:37:00');
insert into ticket_comments values (290, 237, 'Customer', 'Mei Petrova', 'Can you confirm when the fix is released?', timestamp '2026-04-15 22:02:00');
insert into ticket_comments values (291, 238, 'Agent', 'Sofia Marquez', 'Version 3.9.0 crashes when the offline database is larger than 2 GB. Version 3.9.1 fixes it; until it reaches your store, sign out and in again to rebuild the offline data. See article KB-401.', timestamp '2026-03-20 05:48:00');
insert into ticket_comments values (292, 239, 'Agent', 'Arjun Mehta', 'Webhooks are disabled after 24 hours of failed deliveries. Your endpoint returned HTTP 500. Fix the endpoint and re-enable the webhook under Connect > Webhooks; missed events can be replayed from there. See article KB-601.', timestamp '2026-01-17 12:17:00');
insert into ticket_comments values (293, 240, 'Agent', 'Daniel Okafor', 'Offline mode keeps contacts, deals, and the last 90 days of invoices. Open Settings > Offline and tap "Download now" before you travel. See article KB-403.', timestamp '2026-01-18 13:55:00');
insert into ticket_comments values (294, 240, 'Customer', 'Aisha Wong', 'That worked, thank you!', timestamp '2026-01-19 16:12:00');
insert into ticket_comments values (295, 241, 'Agent', 'Priya Raman', 'Analytics shows revenue by payment date and excludes unpaid invoices, while Billing lists invoices by issue date. Switch the dashboard filter to "Issue date" to compare them. See article KB-503.', timestamp '2026-03-29 04:17:00');
insert into ticket_comments values (296, 242, 'Agent', 'Liam Chen', 'Version 3.9.0 crashes when the offline database is larger than 2 GB. Version 3.9.1 fixes it; until it reaches your store, sign out and in again to rebuild the offline data. See article KB-401.', timestamp '2026-08-15 23:03:00');
