insert into ticket_comments values (298, 243, 'Agent', 'Liam Chen', 'The API allows 120 requests per minute on Basic, 600 on Professional, and 3,000 on Enterprise. Use the bulk endpoints and honor the Retry-After header. See article KB-602.', timestamp '2026-02-22 03:39:00');
insert into ticket_comments values (299, 244, 'Agent', 'Sofia Marquez', 'Reset e-mails come from no-reply@atlas.example. Your mail filter quarantined them; please allow that sender. I have triggered a new reset message. See article KB-102.', timestamp '2026-07-11 02:14:00');
insert into ticket_comments values (300, 245, 'Agent', 'Yusuf Demir', 'This is a known issue in 8.4.0 with pipelines that have more than 100 stages of custom fields. It is fixed in 8.4.1; as a workaround, hide unused custom fields on the board. See article KB-301.', timestamp '2026-07-22 22:06:00');
insert into ticket_comments values (301, 246, 'Agent', 'Emma Lindqvist', 'Tax exemptions apply from the next invoice after the number or certificate is verified. I have verified yours and issued a corrected invoice with a credit note for the difference. See article KB-203.', timestamp '2026-02-10 04:29:00');
insert into ticket_comments values (302, 248, 'Agent', 'Liam Chen', 'Every chart has a menu with Export > CSV or Excel. To export a whole dashboard, use the Share button and choose "Data (Excel)". See article KB-502.', timestamp '2026-07-24 18:14:00');
