insert into kb_articles values ('KB-101', null, 'Fixing sign-in problems', 'If you cannot sign in, first check that Caps Lock is off and that you are using the newest password reset link: a link expires after one hour and every new request makes older links invalid. After five failed attempts an account is locked for 15 minutes. Administrators can unlock it at once under Settings > Users > Unlock. If your company uses single sign-on, sign in through your identity provider instead of the Atlas sign-in form.', date '2026-01-10');
insert into kb_articles values ('KB-102', null, 'Password reset e-mails do not arrive', 'Password reset messages are sent from no-reply@atlas.example within one minute. If none arrives, check the spam or quarantine folder and ask your mail administrator to allow that sender. Corporate filters such as Microsoft 365 Defender often hold the message. You can request a new reset link at any time; only the newest link works.', date '2026-01-17');
insert into kb_articles values ('KB-103', null, 'Two-factor authentication', 'Two-factor authentication adds a six-digit code from an authenticator app to every sign-in. Users turn it on under Profile > Security. Administrators can require it for everyone under Settings > Security > Sign-in policy. If codes are rejected, the clock of the phone is probably wrong: turn on automatic date and time. Backup codes are shown once when you set it up; keep them safe.', date '2026-01-24');
insert into kb_articles values ('KB-104', null, 'Users and roles', 'Administrators invite users under Settings > Users > Invite. Each user has one role: Viewer, Sales, Billing, or Administrator. The Billing role is required to see invoices and payment methods. Removing a user frees the seat immediately; their records stay and can be reassigned.', date '2026-01-31');
insert into kb_articles values ('KB-105', null, 'Responding to a suspicious sign-in', 'If you receive an alert about a sign-in you do not recognize, change your password at once and choose "Sign out all sessions" under Profile > Security. Turn on two-factor authentication. The sign-in history under Settings > Security > Activity shows the time, device, and approximate location of every sign-in. Contact support if you believe data was accessed.', date '2026-02-07');
insert into kb_articles values ('KB-201', 2, 'Duplicate charges and refunds', 'A duplicate charge usually happens when the payment gateway times out and the charge is retried. Support refunds the duplicate as soon as it is reported. Refunds appear on card statements within 5 to 10 business days, depending on the bank. Never pay the same invoice manually after an automatic charge has failed without checking the invoice status first.', date '2026-02-14');
insert into kb_articles values ('KB-202', 2, 'Downloading invoices and receipts', 'All invoices and receipts are under Billing > Invoices. Filter by date or status, then use Download all to get a ZIP file with one PDF per invoice. Invoices can also be e-mailed automatically to an accounting address set under Billing > Settings.', date '2026-02-21');
insert into kb_articles values ('KB-203', 2, 'Taxes, VAT, and exemptions', 'Atlas Billing calculates sales tax, VAT, and GST from the customer address. Enter an EU VAT number, a GSTIN, or upload a tax exemption certificate under Billing > Tax details. Exemptions apply from the next invoice after verification, which takes up to one business day. For an invoice already issued, support issues a credit note.', date '2026-02-28');
insert into kb_articles values ('KB-204', 2, 'Changing your plan', 'Upgrades take effect immediately and are prorated to the day, so you pay only the difference for the rest of the billing period. Downgrades take effect at the next renewal date. Change the plan under Billing > Subscription. Enterprise plans include higher API limits and priority support.', date '2026-03-07');
insert into kb_articles values ('KB-205', 2, 'Custom fields on invoices', 'Invoice templates support up to five custom fields, such as a purchase order number or a cost center. Add them under Billing > Templates > Fields, then place them on the template. Values are entered on each invoice or taken from the customer record.', date '2026-03-14');
insert into kb_articles values ('KB-301', 1, 'Pipeline page does not load in 8.4.0', 'In Atlas CRM 8.4.0, the pipeline board can stay on a loading spinner when deal cards show many custom fields. The problem is fixed in 8.4.1. As a workaround, open Pipeline settings > Card fields and hide the custom fields you do not need on the board.', date '2026-03-21');
insert into kb_articles values ('KB-302', 1, 'Avoiding and merging duplicate contacts', 'The contact importer matches existing records by e-mail address. Rows without an e-mail, or with a different one, create new contacts. To clean up after an import, use Contacts > Find duplicates, which compares names, e-mails, and phone numbers and lets you merge records in bulk. Choose "Update existing records" when you import again.', date '2026-03-28');
insert into kb_articles values ('KB-303', 1, 'Revenue forecasts', 'Forecasts estimate the revenue you will close in a period. A weighted forecast multiplies each deal amount by the probability of its stage; stage probabilities are set under Pipeline settings. Create one under Forecasts > New forecast and compare it with actual closed revenue at the end of the quarter.', date '2026-04-04');
insert into kb_articles values ('KB-401', 3, 'Mobile app crashes on startup in 3.9.0', 'Atlas Mobile 3.9.0 can crash on launch when the offline database is larger than 2 GB. Version 3.9.1 fixes the crash. Until the update reaches your app store, sign out and sign in again: this rebuilds the offline data with only the last 90 days.', date '2026-04-11');
insert into kb_articles values ('KB-402', 3, 'Offline edits and sync conflicts', 'Changes made offline are stored on the device for up to 7 days and uploaded when a connection returns. If the same record was changed on the web in the meantime, the newer change wins and the other is listed under Settings > Sync > Conflicts, where you can apply it again.', date '2026-04-18');
insert into kb_articles values ('KB-403', 3, 'Using Atlas Mobile offline', 'Offline mode keeps contacts, deals, and invoices from the last 90 days on the device. Open Settings > Offline and tap Download now before traveling. Invoices created offline get a temporary number until they are uploaded.', date '2026-04-25');
insert into kb_articles values ('KB-501', 4, 'Scheduled reports stop sending', 'A report schedule pauses automatically after three failed deliveries in a row, for example when a recipient address bounces or a mailbox is full. Open Reports > Schedules, remove or correct the failing address, and choose Resume. The schedule history shows every delivery and its result.', date '2026-05-02');
insert into kb_articles values ('KB-502', 4, 'Exporting data from Analytics', 'Every chart and table has a menu with Export, which downloads the data behind it as CSV or Excel. To export a whole dashboard, use Share > Data (Excel): each chart becomes one worksheet. Large exports are e-mailed as a link when they are ready.', date '2026-05-09');
insert into kb_articles values ('KB-503', 4, 'Why Analytics and Billing totals differ', 'Analytics reports revenue by payment date and includes only paid invoices. Billing lists invoices by issue date, paid or not. The two totals for a month therefore differ when invoices are issued in one month and paid in another. Set the dashboard date filter to Issue date to match the Billing view.', date '2026-05-16');
insert into kb_articles values ('KB-601', 5, 'Webhooks are disabled after failures', 'Atlas Connect retries a failed webhook delivery for 24 hours. After that, the webhook is disabled and the account owner is notified. Fix the endpoint so that it returns HTTP 2xx, then re-enable the webhook under Connect > Webhooks. Use Replay to resend the events missed while it was disabled.', date '2026-05-23');
insert into kb_articles values ('KB-602', 5, 'API rate limits', 'The REST API allows 120 requests per minute on the Basic plan, 600 on Professional, and 3,000 on Enterprise. When the limit is reached, the API returns HTTP 429 with a Retry-After header saying how many seconds to wait. Bulk endpoints accept up to 100 records per call and count as one request.', date '2026-05-30');
insert into kb_articles values ('KB-603', 5, 'Calendar integration', 'Atlas Connect syncs meetings with Microsoft 365 and Google Workspace calendars in both directions every five minutes. Set it up under Connect > Connectors by choosing the provider and signing in with the calendar account. Each user connects their own calendar.', date '2026-06-06');
insert into kb_articles values ('KB-701', 6, 'Atlas Sync is stuck', 'Atlas Sync stops on files it cannot upload: names longer than 255 characters, names with characters such as : ? * or |, and files locked by another program. The app log, under Help > Show log, lists them. Rename or close the files and choose Retry all. Large first uploads can take several hours.', date '2026-06-13');
insert into kb_articles values ('KB-702', 6, 'Deploying Atlas Sync to many computers', 'For company-wide rollouts, download the MSI package for Windows or the PKG for macOS under Settings > Downloads > Enterprise. Both install silently and can be deployed with Microsoft Intune, Jamf, or any tool that runs installers. The deployment guide lists the options, such as the account URL and single sign-on.', date '2026-06-20');
